const inputData = $input.first().json;
const body = inputData.body || inputData;
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// Public RAG access: profile_id is optional. Anyone can ask a policy question;
// a bank customer is simply recognized (profile_id set), everyone else is
// tracked by their verified sender email only (customer_email).
const profileId = body.profile_id && uuidRegex.test(String(body.profile_id).trim()) ? String(body.profile_id).trim() : null;
// Registered-customer calls from WF-00 pass the raw email metadata object
// through (fromEmail), not the customer_email/inquiry field names -- accept
// both so a real send-to address is always available downstream.
const customerEmail = String(body.customer_email || body.fromEmail || '').trim().toLowerCase();

if (!profileId && !customerEmail) {
  throw new Error('Either profile_id or customer_email is required to identify the inquirer');
}

const subject = String(body.subject || '').trim();
// Defensive fallback: if the body/inquiry text is empty (e.g. an email with
// everything crammed into the subject line), fall back to the subject rather
// than hard-failing the whole sub-workflow with no reply to the customer.
const inquiry = String(body.inquiry || body.bodyText || '').trim() || subject;
if (!inquiry) {
  throw new Error('inquiry text is required');
}

return [{
  json: {
    isValid: true,
    params: {
      profile_id: profileId,
      customer_email: customerEmail,
      inquirer_type: profileId ? 'customer' : 'public',
      subject: subject || 'General Banking Inquiry',
      inquiry: inquiry
    }
  }
}];

const params = $('Validate Support Request Payload').item.json.params;
const caseInsertResult = $('Create Support Case in Supabase').item.json;
const caseId = caseInsertResult.id;
const recentCases = $input.all();
const isReturning = Array.isArray(recentCases) && recentCases.length > 1;

return [{
  json: {
    case_id: caseId,
    profile_id: params.profile_id,
    subject: params.subject,
    inquiry: params.inquiry,
    customer_email: params.customer_email,
    inquirer_type: params.inquirer_type,
    isReturning
  }
}];

