=Hello,

{{ $('Save Support Case Draft in Supabase').item.json.groq_draft }}

Reference: {{ $('Extract Case ID').item.json.case_id }}

This answer is grounded in our official policy documents. If it doesn't fully address your question, just reply and a specialist will follow up.

Digital Bank Customer Support

=A customer asked a policy question. The assistant's draft is below. Nothing has been sent to them yet - it needs your decision first.

Customer: {{ $('Validate Support Request Payload').item.json.params.customer_email }}
Subject: {{ $('Validate Support Request Payload').item.json.params.subject }}
Case reference: {{ $('Extract Case ID').item.json.case_id }}
Confidence: {{ $('Save Support Case Draft in Supabase').item.json.confidence_score }}
Sources: {{ $('Save Support Case Draft in Supabase').item.json.rag_doc_ids && String($('Save Support Case Draft in Supabase').item.json.rag_doc_ids).replace(/[\[\]"]/g, '') || 'none - nothing relevant was retrieved' }}

THEIR QUESTION
{{ $('Validate Support Request Payload').item.json.params.inquiry }}

DRAFT ANSWER (not sent)
{{ $('Save Support Case Draft in Supabase').item.json.groq_draft }}

HOW TO DECIDE
Reply to this email with a single word on the first line:

    APPROVE
or
    REJECT

APPROVE sends the draft above to the customer as it stands. To send something different, reply APPROVE and add a line starting with NOTE: followed by the wording you want sent instead - that text replaces the draft. REJECT closes the case without emailing the customer.

Keep the reference {{ $json.ref_code }} in the reply - it is already in the subject line, so a normal reply works. Your reply must contain APPROVE or REJECT but not both. This reference expires in 7 days.

===BANKING-OPS-ACTION===
REF: {{ $json.ref_code }}
TYPE: support_draft
========================

parameters.jsCode:
// The agent answers in plain text (see the system prompt) instead of structured
// JSON, because the Groq model available on this account
// (openai/gpt-oss-safeguard-20b) intermittently fails a structured-output call
// outright -- confirmed live: retrieval succeeded perfectly and the agent still
// errored trying to emit JSON. Plain text with labeled lines is far more robust
// against that failure mode. Output is reshaped into the same { output: {...} }
// envelope the rest of the workflow already expects, so nothing downstream changed.
const raw = String($json.output || $json.text || '').trim();

const LABELS = 'DRAFT|GROUNDED|CONFIDENCE|CITATIONS|NEEDS_HUMAN';

function field(label) {
  // NOTE: deliberately NO 'm' flag. With it, `$` matches end-of-LINE, so the lazy
  // capture below stops at the first blank line and a two-paragraph answer gets
  // truncated to its first paragraph -- which is exactly what happened on the
  // first live test. Line-start is anchored explicitly with (?:^|\n) instead.
  const re = new RegExp(
    '(?:^|\\n)[ \\t]*' + label + '[ \\t]*:[ \\t]*([\\s\\S]*?)(?=\\n[ \\t]*(?:' + LABELS + ')[ \\t]*:|$)',
    'i'
  );
  const m = raw.match(re);
  return m ? m[1].trim() : null;
}

const FALLBACK_DRAFT = 'Thank you for contacting Digital Bank. We were unable to find a confirmed answer to your question in our policy documents. A specialist will review your question and send you an accurate, verified answer shortly.';

const draftText = field('DRAFT');
const groundedText = field('GROUNDED');
const confidenceText = field('CONFIDENCE');
const citationsText = field('CITATIONS');
const needsHumanText = field('NEEDS_HUMAN');

// If the model didn't follow the format at all, fail safe exactly like an agent
// error: no draft, not grounded, needs a human. Never guess a confident answer
// out of unparseable text.
if (!draftText) {
  return [{ json: { output: {
    draft: FALLBACK_DRAFT,
    grounded: false, confidence: 0, citations: [], needs_human: true,
    parse_failed: true, raw_output: raw.slice(0, 500)
  } } }];
}

let grounded = /^true$/i.test(groundedText || '');
let confidence = parseFloat(confidenceText);
if (isNaN(confidence)) confidence = 0;
confidence = Math.max(0, Math.min(1, confidence));

const citations = (citationsText && !/^none$/i.test(citationsText))
  ? citationsText.split(',').map(s => s.trim()).filter(Boolean)
  : [];

let needsHuman = needsHumanText ? /^true$/i.test(needsHumanText) : !grounded;

// GUARDRAIL: an answer that claims to be grounded but points at nothing.
//
// The confidence threshold alone cannot catch this. A model that has drifted
// onto a similar-but-wrong document, or that is reciting plausible banking
// knowledge it was trained on rather than OUR policy, reports high confidence
// and no citation -- it has nothing to cite because nothing it used came from
// the knowledge base. That is the exact failure this bank cannot ship: a
// confident, fluent, invented fee or limit.
//
// So grounded + zero citations is treated as NOT grounded, whatever the model
// says about its own confidence, and goes to a human.
let citationGuardTripped = false;
if (grounded && citations.length === 0) {
  citationGuardTripped = true;
  grounded = false;
  needsHuman = true;
  confidence = 0;
}

// GUARDRAIL: a multi-part question answered only in part.
//
// A customer sent six numbered questions. The agent answered two, wrote
// "3. The policy does not cover any additional information beyond the above"
// to stand for the rest, and reported grounded with confidence 0.95 and no
// human needed -- so it went straight out. Four of those six were fully
// covered by our documents; it had simply never searched for them.
//
// Neither existing guard can see this. The citation guard checks that an
// answer points at something, and this one did. The threshold checks how
// sure the model is, and it was sure -- correctly, about the third of the
// question it had actually read. Confidence says nothing about coverage.
//
// So when the customer numbers their questions, the draft has to reach
// their last number. If it does not, a human sees it instead of it going out.
function numberedItems(text) {
  const found = new Set();
  const re = /(?:^|\n)[ \t>]*(\d{1,2})[.)][ \t]+\S/g;
  let m;
  while ((m = re.exec(text)) !== null) found.add(parseInt(m[1], 10));
  return found;
}
const askedNumbers = numberedItems(String($('Extract Case ID').item.json.inquiry || ''));
let answerTruncated = false;
if (askedNumbers.size >= 3) {
  const lastAsked = Math.max.apply(null, Array.from(askedNumbers));
  if (!numberedItems('\n' + draftText).has(lastAsked)) {
    answerTruncated = true;
    needsHuman = true;
  }
}

return [{ json: { output: {
  draft: citationGuardTripped ? FALLBACK_DRAFT : draftText,
  grounded, confidence, citations, needs_human: needsHuman,
  citation_guard_tripped: citationGuardTripped,
  answer_truncated: answerTruncated
} } }];
